(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x * 0.02 + t * 0.3) * 15 + Math.cos(y * 0.015 - t * 0.2) * 10;
  const w1y = Math.cos(y * 0.02 - t * 0.25) * 15 + Math.sin(x * 0.018 + t * 0.35) * 10;
  const nx = x + w1x, ny = y + w1y;
  const w2x = Math.sin(nx * 0.025 - t * 0.4) * 8 + Math.cos(ny * 0.02 + t * 0.3) * 6;
  const w2y = Math.cos(ny * 0.022 + t * 0.35) * 8 + Math.sin(nx * 0.019 - t * 0.45) * 6;
  const sx = nx + w2x, sy = ny + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+4)*40, 0.085, 1.8],
    [200+Math.sin(t*0.38+6)*110, 220+Math.cos(t*0.48+3)*70, 0.065, 2.4],
    [300+Math.cos(t*0.42+1)*90, 100+Math.sin(t*0.62+5)*60, 0.095, 2.0]
  ];
  let aS = 0, iS = 0, hS = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    hS += Math.cos(d*f*1.3 - t*sp*0.8 + 2.0);
  }
  const n = src.length, act = aS/n, inh = iS/n, hlg = hS/n;
  const bg1 = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2 = (Math.sin(sx*0.08-sy*0.06+t*1.6) + Math.cos(sx*0.07+sy*0.09-t*1.3))/2;
  const bg3 = (Math.sin(sx*0.15+sy*0.12+t*2.5) + Math.cos(sx*0.13-sy*0.17-t*2.2))/2;
  const bg = bg1 + bg2*0.4 + bg3*0.15;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.3;
  const sp2 = (Math.sin(dist*0.07+ang*2+t*0.9) + Math.cos(dist*0.06-ang*5+t*1.8))*0.2;
  const spiral = sp1 + sp2;
  const mx1 = Math.sin(sx*0.2)*Math.sin(sy*0.2);
  const mx2 = Math.sin((sx+3)*0.2)*Math.sin((sy+3)*0.2);
  const moire = (mx1 - mx2) * 5;
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const rd1 = Math.tanh((act - inh*0.7 + bg*0.3 + spiral)*2.2);
  const rd2 = Math.tanh((hlg*0.5 - act*0.3 + inh*0.4 + moire*0.15)*1.8);
  const reaction = rd1*0.65 + rd2*0.35;
  const micro = Math.sin(sx*0.4+t*3)*Math.sin(sy*0.4-t*2.5)*0.1;
  const blend = reaction*0.6 + cell*0.25 + micro*0.15;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,42],[10,45,75],[15,95,110],[25,155,135],
    [120,195,130],[220,200,80],[235,150,75],
    [210,90,70],[160,50,70],[90,25,65],[35,15,55],[5,12,42]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.75 + Math.sin(reaction*Math.PI)*0.2 + Math.abs(rd2)*0.05;
  const edge = Math.abs(reaction)>0.75?1.2+Math.abs(reaction)*0.1:Math.abs(reaction)>0.5?1.05:1.0;
  const hs = Math.sin(ang*2+t*0.5)*0.05;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge*(1+hs)))|0,
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge))|0,
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge*(1-hs)))|0
  ];
}
